// Interactive 3D visualization of amino acid chain folding into protein structure

import * as THREE from 'https://esm.sh/three@0.160.0';
import { OrbitControls } from 'https://esm.sh/three@0.160.0/examples/jsm/controls/OrbitControls.js';

// Scene setup
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x0a0a1a);

const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
camera.position.set(0, 0, 35);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
document.body.appendChild(renderer.domElement);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.autoRotate = true;
controls.autoRotateSpeed = 1.0;

// Lights
const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
scene.add(ambientLight);

const pointLight = new THREE.PointLight(0xffffff, 1.2, 100);
pointLight.position.set(10, 10, 10);
scene.add(pointLight);

const pointLight2 = new THREE.PointLight(0x88ccff, 0.6, 100);
pointLight2.position.set(-10, -5, 10);
scene.add(pointLight2);

const pointLight3 = new THREE.PointLight(0xffaa88, 0.4, 100);
pointLight3.position.set(5, -10, -5);
scene.add(pointLight3);

// Amino acid properties
const AMINO_ACIDS = [
  { name: 'Alanine', abbr: 'A', color: 0x4a90d9, type: 'nonpolar' },
  { name: 'Arginine', abbr: 'R', color: 0xe74c3c, type: 'positive' },
  { name: 'Asparagine', abbr: 'N', color: 0x9b59b6, type: 'polar' },
  { name: 'Aspartic', abbr: 'D', color: 0xf39c12, type: 'negative' },
  { name: 'Cysteine', abbr: 'C', color: 0xf1c40f, type: 'polar' },
  { name: 'Glutamic', abbr: 'E', color: 0xe67e22, type: 'negative' },
  { name: 'Glutamine', abbr: 'Q', color: 0x8e44ad, type: 'polar' },
  { name: 'Glycine', abbr: 'G', color: 0x7f8c8d, type: 'nonpolar' },
  { name: 'Histidine', abbr: 'H', color: 0xc0392b, type: 'positive' },
  { name: 'Isoleucine', abbr: 'I', color: 0x3498db, type: 'nonpolar' },
  { name: 'Leucine', abbr: 'L', color: 0x2980b9, type: 'nonpolar' },
  { name: 'Lysine', abbr: 'K', color: 0xe74c3c, type: 'positive' },
  { name: 'Methionine', abbr: 'M', color: 0x16a085, type: 'nonpolar' },
  { name: 'Phenylalanine', abbr: 'F', color: 0x1abc9c, type: 'nonpolar' },
  { name: 'Proline', abbr: 'P', color: 0x27ae60, type: 'nonpolar' },
  { name: 'Serine', abbr: 'S', color: 0x9b59b6, type: 'polar' },
  { name: 'Threonine', abbr: 'T', color: 0x8e44ad, type: 'polar' },
  { name: 'Tryptophan', abbr: 'W', color: 0x2ecc71, type: 'nonpolar' },
  { name: 'Tyrosine', abbr: 'Y', color: 0xd35400, type: 'polar' },
  { name: 'Valine', abbr: 'V', color: 0x34495e, type: 'nonpolar' },
];

const CHAIN_LENGTH = 60;
const aminoAcidData = [];
for (let i = 0; i < CHAIN_LENGTH; i++) {
  aminoAcidData.push(AMINO_ACIDS[i % AMINO_ACIDS.length]);
}

// Create amino acid spheres
const sphereGeometry = new THREE.SphereGeometry(0.8, 32, 32);
const aminoAcidMeshes = [];

aminoAcidData.forEach((aa, i) => {
  const material = new THREE.MeshPhysicalMaterial({
    color: aa.color,
    metalness: 0.1,
    roughness: 0.3,
    clearcoat: 0.8,
    clearcoatRoughness: 0.2,
    emissive: aa.color,
    emissiveIntensity: 0.15,
  });
  const mesh = new THREE.Mesh(sphereGeometry, material);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  scene.add(mesh);
  aminoAcidMeshes.push(mesh);
});

// Create bonds between amino acids
const bondMaterial = new THREE.MeshStandardMaterial({
  color: 0xaaaaaa,
  metalness: 0.5,
  roughness: 0.5,
});
const bondGeometry = new THREE.CylinderGeometry(0.15, 0.15, 1, 8);
const bondMeshes = [];

for (let i = 0; i < CHAIN_LENGTH - 1; i++) {
  const bond = new THREE.Mesh(bondGeometry, bondMaterial);
  bond.castShadow = true;
  scene.add(bond);
  bondMeshes.push(bond);
}

// Secondary structure indicators
// Alpha helix: HHHH region, Beta sheet: EEEE region
const SS_TYPES = [];
for (let i = 0; i < CHAIN_LENGTH; i++) {
  if (i >= 10 && i < 22) SS_TYPES.push('H'); // Alpha helix
  else if (i >= 30 && i < 38) SS_TYPES.push('E'); // Beta strand
  else if (i >= 45 && i < 52) SS_TYPES.push('H'); // Another helix
  else SS_TYPES.push('C'); // Coil/loop
}

// Store unfolded (linear) and folded positions
const unfoldedPositions = [];
const foldedPositions = [];

for (let i = 0; i < CHAIN_LENGTH; i++) {
  // Unfolded: straight line with slight randomness
  unfoldedPositions.push(new THREE.Vector3((i - CHAIN_LENGTH / 2) * 1.6, 0, 0));

  // Folded: 3D structure with helices and sheets
  let pos = new THREE.Vector3();

  if (SS_TYPES[i] === 'H') {
    // Alpha helix: spiral
    const helixIndex = (i >= 10 && i < 22) ? i - 10 : i - 45;
    const helixCenter = (i >= 10 && i < 22) ? new THREE.Vector3(-8, 2, 0) : new THREE.Vector3(6, -4, 4);
    const angle = helixIndex * 1.8; // ~100 degrees per residue
    const radius = 2.5;
    const rise = 1.3;
    pos.set(
      helixCenter.x + Math.cos(angle) * radius,
      helixCenter.y + helixIndex * rise - ((i >= 10 && i < 22) ? 4 : 2),
      helixCenter.z + Math.sin(angle) * radius
    );
  } else if (SS_TYPES[i] === 'E') {
    // Beta sheet: zigzag plane
    const strandIndex = i - 30;
    const zigzag = (strandIndex % 2 === 0) ? 1 : -1;
    pos.set(
      -2 + strandIndex * 1.2,
      zigzag * 2.5,
      5
    );
  } else {
    // Coil/loop: smooth curves connecting structures
    if (i < 10) {
      // N-terminus tail
      const t = i / 10;
      pos.set(-14 + i * 1.2, Math.sin(t * Math.PI) * 2, Math.cos(t * Math.PI) * 1.5);
    } else if (i >= 22 && i < 30) {
      // Loop between helix 1 and sheet
      const t = (i - 22) / 8;
      pos.set(
        -5 + t * 3,
        2 + Math.sin(t * Math.PI) * 3,
        2 + t * 3
      );
    } else if (i >= 38 && i < 45) {
      // Loop between sheet and helix 2
      const t = (i - 38) / 7;
      pos.set(
        3 + Math.sin(t * Math.PI) * 2,
        -1 - t * 2,
        5 - t * 4
      );
    } else {
      // C-terminus tail
      const t = (i - 52) / 8;
      pos.set(
        8 + t * 2,
        -4 + Math.sin(t * Math.PI) * 1,
        4 - t * 2
      );
    }
  }
  foldedPositions.push(pos);
}

// Animation state
let isFolding = true;
let foldProgress = 0;
let foldSpeed = 0.003;
let unfoldedOnce = false;
let reverseDirection = false;

// Labels
const labelDiv = document.createElement('div');
labelDiv.style.cssText = 'position:absolute;top:10px;left:10px;color:#fff;font-family:Segoe UI,sans-serif;pointer-events:none;';
document.body.appendChild(labelDiv);

function updateLabel() {
  const status = foldProgress < 0.1 ? 'Unfolded (Primary Structure)' :
    foldProgress < 0.5 ? 'Folding in Progress...' :
    foldProgress < 0.9 ? 'Secondary Structure Forming' :
    'Folded (Tertiary Structure)';
  labelDiv.innerHTML = `
    <div style="background:rgba(0,0,0,0.6);padding:15px;border-radius:10px;max-width:320px;">
      <h2 style="margin:0 0 8px 0;color:#4fc3f7;font-size:18px;">🧬 Protein Folding Simulation</h2>
      <p style="margin:4px 0;font-size:14px;"><b>Status:</b> <span style="color:#81c784">${status}</span></p>
      <p style="margin:4px 0;font-size:13px;color:#aaa;">Chain: ${CHAIN_LENGTH} amino acids</p>
      <p style="margin:4px 0;font-size:12px;color:#bbb;line-height:1.4;">
        🔵 <span style="color:#4a90d9">Blue</span> = Nonpolar<br>
        🟣 <span style="color:#9b59b6">Purple</span> = Polar<br>
        🔴 <span style="color:#e74c3c">Red</span> = Positive charge<br>
        🟠 <span style="color:#f39c12">Orange</span> = Negative charge
      </p>
      <p style="margin:8px 0 0 0;font-size:11px;color:#888;">Drag to rotate • Scroll to zoom</p>
    </div>
  `;
}

// UI Controls
const btnDiv = document.createElement('div');
btnDiv.style.cssText = 'position:absolute;bottom:20px;left:50%;transform:translateX(-50%);display:flex;gap:10px;';
document.body.appendChild(btnDiv);

function createButton(text, onClick) {
  const btn = document.createElement('button');
  btn.innerText = text;
  btn.style.cssText = 'padding:10px 18px;background:#4fc3f7;border:none;border-radius:8px;color:#000;font-weight:bold;cursor:pointer;font-family:Segoe UI,sans-serif;font-size:14px;transition:all 0.2s;';
  btn.onmouseenter = () => btn.style.background = '#29b6f6';
  btn.onmouseleave = () => btn.style.background = '#4fc3f7';
  btn.onclick = onClick;
  return btn;
}

btnDiv.appendChild(createButton('⏪ Reset / Unfold', () => {
  reverseDirection = true;
  isFolding = true;
  controls.autoRotate = false;
}));
btnDiv.appendChild(createButton('▶️ Fold Protein', () => {
  reverseDirection = false;
  isFolding = true;
  controls.autoRotate = false;
}));
btnDiv.appendChild(createButton('🔄 Auto Rotate', () => {
  controls.autoRotate = !controls.autoRotate;
}));

// Animation loop
function animate() {
  requestAnimationFrame(animate);

  if (isFolding) {
    if (reverseDirection) {
      foldProgress -= foldSpeed;
      if (foldProgress <= 0) {
        foldProgress = 0;
        isFolding = false;
      }
    } else {
      foldProgress += foldSpeed;
      if (foldProgress >= 1) {
        foldProgress = 1;
        isFolding = false;
      }
    }
  }

  // Smooth ease function
  const t = foldProgress < 0.5 ? 4 * foldProgress * foldProgress * foldProgress :
    1 - Math.pow(-2 * foldProgress + 2, 3) / 2;

  // Update amino acid positions
  for (let i = 0; i < CHAIN_LENGTH; i++) {
    const start = unfoldedPositions[i];
    const end = foldedPositions[i];
    aminoAcidMeshes[i].position.lerpVectors(start, end, t);

    // Add subtle breathing animation when folded
    if (foldProgress > 0.8) {
      const time = Date.now() * 0.001;
      aminoAcidMeshes[i].position.y += Math.sin(time + i * 0.5) * 0.02;
    }
  }

  // Update bond positions and rotations
  for (let i = 0; i < CHAIN_LENGTH - 1; i++) {
    const p1 = aminoAcidMeshes[i].position;
    const p2 = aminoAcidMeshes[i + 1].position;
    const mid = new THREE.Vector3().addVectors(p1, p2).multiplyScalar(0.5);
    bondMeshes[i].position.copy(mid);
    bondMeshes[i].lookAt(p2);
    bondMeshes[i].scale.y = p1.distanceTo(p2);
  }

  updateLabel();
  controls.update();
  renderer.render(scene, camera);
}

// Handle resize
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});

// Start with folded state
foldProgress = 0;
reverseDirection = false;
isFolding = true;

animate();

